async function importNotes(rows, save, { batchSize, timeoutMs }) {
  const saved = [], failed = [];
  for (let i = 0; i < rows.length; i++) {
    try {
      await save(rows[i]);
      saved.push(i);
    } catch (e) {
      failed.push({ index: i, reason: e.message });
    }
  }
  return { saved, failed };
}

